import pandas as pd

def class_performance(scores: pd.DataFrame) -> pd.DataFrame:
    totals = scores['assignment1'] + scores['assignment2'] + scores['assignment3']
    diff = int(totals.max() - totals.min()) if not totals.empty else 0
    return pd.DataFrame({'difference_in_score': [diff]})
